#include "rules/FrozenTemplates.h"
#include <fstream>
#include <iostream>
using namespace worldgen_rules;
using J=nlohmann::json;
using Key=std::array<int,3>;
void check(bool v,char const*why){if(!v)throw std::runtime_error(why);}
Key key(StructurePoint p){return {p.x,p.y,p.z};}
StructurePoint markerPoint(FrozenRuinPart const&p,LegacyDataMarker const&m){auto[x,z]=rotateVillageXZ(m.local.x,m.local.z,p.rotation);return {p.origin.x+x,p.origin.y+m.local.y,p.origin.z+z};}
FrozenRuinPart part(J const&model,int rotation){auto s=model.at("size");StructurePoint origin{-45,19,-29};FrozenRuinPart p{model.at("name"),origin,rotatedTemplateBounds({s[0],s[1],s[2]},origin,rotation),rotation,{}};for(auto const&m:model.at("rawMarkers")){auto q=m.at("local");p.markers.push_back({{q[0],q[1],q[2]},m.at("label")});}return p;}
struct Result {J states=J::array(),loot=J::array();size_t places{},markers{},reads{};};
Result run(FrozenRuinProgram const&program,std::vector<StructureBox>const&clips,bool existing){
 std::map<Key,std::string>world;std::map<Key,std::pair<size_t,uint32_t>>loot;std::map<VillageXZ,std::vector<size_t>>placed;Result result;StructureBox active;
 for(auto const&clip:clips){placed.clear();executeFrozenRuins(program,clip,[&](size_t i,auto const&p,uint32_t seed,auto const&owner){active=owner;ChunkPosition cp{spacingCell(owner.min.x,16),spacingCell(owner.min.z,16)};check(seed==placementSeed(cp.x,cp.z,146731024+int(i),program.worldSeed),"native layer seed differs from LLBDS");placed[{cp.x,cp.z}].push_back(i);++result.places;
   // Controlled native-layer callback: later layers cover earlier chests.
   // Actual native processors and final block states are NOT executed here.
   for(auto const&m:p.markers){auto q=markerPoint(p,m);if(m.label=="chest"&&inStructureOwner(q,owner))world[key(q)]=existing?"minecraft:chest":"minecraft:gravel";}
  },[&](StructurePoint q){check(inStructureOwner(q,active),"ruin marker read foreign owner");++result.reads;auto it=world.find(key(q));return it!=world.end()&&it->second=="minecraft:chest";},[&](auto const&m,uint32_t seed,auto const&owner){check(inStructureOwner(m.position,owner),"ruin marker escaped owner");auto cp=VillageXZ{spacingCell(owner.min.x,16),spacingCell(owner.min.z,16)};std::vector<size_t>expected;for(auto i:program.owners.at(cp))if(program.parts[i].bounds.intersectsXZ(owner))expected.push_back(i);check(placed.at(cp)==expected,"chest finalized before all native layers");check(seed==placementSeed(m.position.x,m.position.z,146731024,program.worldSeed),"ruin marker seed differs from LLBDS");check(loot.emplace(key(m.position),std::pair{m.part,seed}).second,"duplicate cold-layer chest finalized twice");world[key(m.position)]="minecraft:chest";++result.markers;});}
 for(auto const&[p,n]:world)result.states.push_back({p[0],p[1],p[2],n});for(auto const&[p,l]:loot)result.loot.push_back({p[0],p[1],p[2],l.first,l.second});return result;
}
std::vector<StructureBox>ownerClips(FrozenRuinProgram const&p){std::vector<StructureBox>out;for(auto const&[owner,indices]:p.owners)out.push_back({{owner.first*16,-64,owner.second*16},{owner.first*16+15,319,owner.second*16+15}});return out;}
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("report.json asset-catalog.json");J fixture;{std::ifstream f(argv[2]);f>>fixture;}check(fixture.at("models").size()==49,"raw ruin catalog incomplete");std::map<std::string,J const*,std::less<>>models;for(auto const&m:fixture.at("models"))models.emplace(m.at("name").get<std::string>(),&m);
 J cases=J::array(),layerCases=J::array();size_t calls=0,markers=0;
 for(auto const&model:fixture.at("models"))for(int rotation=0;rotation<4;++rotation){auto program=compileFrozenRuins({-3,-2},0xfedcba98u,{part(model,rotation)});auto clips=ownerClips(program);auto forward=run(program,clips,false);std::reverse(clips.begin(),clips.end());auto reverse=run(program,clips,false);check(forward.states==reverse.states&&forward.loot==reverse.loot,"ruin result depends on owner generation order");auto reconstructed=compileFrozenRuins(program.anchor,program.worldSeed,program.parts);auto again=run(reconstructed,clips,false);check(again.states==forward.states&&again.loot==forward.loot,"ruin program reconstruction differs");auto retained=run(program,clips,true);check(retained.markers==0&&retained.loot.empty(),"existing native chests were reseeded");
  auto whole=run(program,{{{-1024,-64,-1024},{1023,319,1023}}},false);check(whole.states==forward.states&&whole.loot==forward.loot,"whole/multiple-owner callback differs from separate owners");calls+=forward.places;markers+=forward.markers;cases.push_back({{"template",model.at("name")},{"rotation",rotation},{"bounds",structureBoxJson(program.bounds)},{"owners",program.owners.size()},{"states",forward.states},{"loot",forward.loot}});
 }
 for(int rotation=0;rotation<4;++rotation){std::vector<FrozenRuinPart>parts;for(auto name:{"ruin/big_ruin1_brick","ruin/big_ruin1_cracked","ruin/big_ruin1_mossy"})parts.push_back(part(*models.at(name),rotation));auto program=compileFrozenRuins({-3,-2},42,std::move(parts));size_t count=0;for(auto const&[owner,rows]:program.chests)count+=rows.size();check(count==1,"actual native cold layers do not share one deduplicated chest");auto clips=ownerClips(program);auto r=run(program,clips,false);check(r.markers==1&&r.loot.at(0).at(3)==0,"duplicate chest did not keep upstream first native layer");std::reverse(clips.begin(),clips.end());auto reverse=run(program,clips,false);check(r.states==reverse.states&&r.loot==reverse.loot,"cold-layer marker result depends on fragment order");layerCases.push_back({{"rotation",rotation},{"placements",r.places},{"loot",r.loot}});}
 auto single=compileFrozenRuins({-3,-2},42,{part(*models.begin()->second,0)});auto clip=ownerClips(single).front();int middle=(clip.min.x+clip.max.x)/2;std::vector<StructureBox>partial{{{clip.min.x,-64,clip.min.z},{middle,319,clip.max.z}},{{middle+1,-64,clip.min.z},{clip.max.x,319,clip.max.z}}};auto a=run(single,partial,false);std::reverse(partial.begin(),partial.end());auto b=run(single,partial,false);check(a.states==b.states&&a.loot==b.loot,"partial native owner callbacks changed marker ownership");int outside=0;executeFrozenRuins(single,{{2000,-64,2000},{2015,319,2015}},[&](auto,auto const&,auto,auto const&){++outside;},[&](auto){++outside;return false;},[&](auto const&,auto,auto const&){++outside;});check(outside==0,"non-overlap ruin callback accessed game state");
 J report={{"passed",true},{"singleTemplateCases",cases.size()},{"nativeLayerCalls",calls},{"finalizedMarkers",markers},{"cases",cases},{"coldLayerCases",layerCases},{"rawModels",fixture.at("models")},{"existingChestsPreserved",true},{"allLayersBeforeFinalMarkers",true},{"firstDuplicateMarkerRetained",true},{"oppositeOrderEqual",true},{"programReconstructionEqual",true},{"wholeOwnerAndPartialClipsChecked",true},{"nonOverlapNoGameCalls",true},{"nativeTemplatePlacementExecuted",false},{"fullNativeProcessorsExecuted",false},{"actualNativeLootExecuted",false},{"nativeReloadVerified",false},{"gameplayTestPerformed",false}};std::ofstream out(argv[1]);out<<report.dump(2)<<'\n';if(!out)throw std::runtime_error("report failed");std::cout<<"Shared frozen ruin layer/owner/final-marker contract passed\n";return 0;
 }catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
